import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{r as l,o as _,c as a,a as o,b as e,e as r,d as s,f as i}from"./app-ae49b443.js";const c={},p={href:"https://jdhao.github.io/2020/07/05/how_to_find_casue_of_technical_issues/",target:"_blank",rel:"noopener noreferrer"},d={href:"https://stackoverflow.com/help/minimal-reproducible-example",target:"_blank",rel:"noopener noreferrer"},m=i("<p>文中提出以下观点：</p><blockquote><p>通过构造MWE，我们能不断缩小问题的范围，定位问题的根源，而不是表面的现象，例如代码在 Linux 上运行错误，我们不能把代码错误归结为操作系统原因，这个范围太庞大，无助于解决问题。</p><ul><li>大项目，可以根据报错信息，在代码中加入log，用来锁定出错位置。</li></ul><p>锁定位置后，可以用如下方法判断问题所在：</p><ol><li>新建一个简单的项目用来复现此问题。做到代码最少，引用、安装最小。</li><li>试着把问题代码<strong>注释</strong>，或者<strong>换一种写法</strong>，看是否还会出现。注意依赖的库的版本。</li></ol><p>如果自己还是解决不了，在 stackoverflow 或者 github 上提供 MWE，也更有可能得到别人的回复。</p></blockquote><p>一般锁定位置后，后续问题就比较好找到了。上面只提到了用log来锁定位置，除此之外，还有其它方法吗？</p>",3),u={href:"https://blog.csdn.net/weixin_33827965/article/details/92424615",target:"_blank",rel:"noopener noreferrer"};function f(h,g){const t=l("ExternalLinkIcon");return _(),a("div",null,[o("p",null,[e("今天读到一篇关于"),o("a",p,[e("定位技术问题的文章"),r(t)]),e("，文中提出一个概念："),o("a",d,[e("MWE"),r(t)]),e("，minimal working example，即“一个最小的能够复现错误的环境”。感觉比较有意思。")]),s(" more "),m,o("ul",null,[o("li",null,[e("除了本地debug外，可以搜索一下，自己用的编程工具可不可以远程调试，比如idea就支持这一操作。idea设置可参考"),o("a",u,[e("IDEA中使用Remote来远程调试程序"),r(t)]),e("。")])])])}const x=n(c,[["render",f],["__file","效率_2022-09-01_如何找到技术问题根源.html.vue"]]);export{x as default};
